/* mbx_layout.h - E4a mailbox v1 layout (docs/soc/e4a_mailbox.md).
 * GENERATED by scripts/gen/gen_mailbox.py from host/ps_mailbox/protocol.py and rtl/soc/soc_addr_map.vh. Do not edit. */
#ifndef MBX_LAYOUT_H
#define MBX_LAYOUT_H

#define MBX_BASE           0x20020000u   /* CPU address of the mailbox window */
#define MBX_SIZE           0x1000u
#define MBX_MAGIC          0x4D425831u
#define MBX_VERSION        0x00010000u
#define MBX_RING_SIZE      16u
#define MBX_RECORD_SIZE    64u
#define MBX_RING_OFFSET    0x100u

/* header byte offsets (writer: cpu / ps) */
#define MBX_H_MAGIC                0x000u   /* cpu: 0x4D425831 'MBX1' once the header is valid */
#define MBX_H_VERSION              0x004u   /* cpu: major << 16 | minor */
#define MBX_H_RING_SIZE            0x008u   /* cpu: number of record slots */
#define MBX_H_RECORD_SIZE          0x00Cu   /* cpu: bytes per record */
#define MBX_H_RING_OFFSET          0x010u   /* cpu: byte offset of slot 0 */
#define MBX_H_RESET_EPOCH          0x014u   /* cpu: +1 on every producer start (>= 1) */
#define MBX_H_STATE                0x018u   /* cpu: producer state, STATE_* */
#define MBX_H_PRODUCER_INDEX       0x01Cu   /* cpu: records published (free-running u32) */
#define MBX_H_EPOCH_START_INDEX    0x020u   /* cpu: PRODUCER_INDEX at the start of this epoch */
#define MBX_H_PUBLISHED_CNT        0x024u   /* cpu: records published in this epoch */
#define MBX_H_RESULT_CNT           0x028u   /* cpu: CNN results taken from the result FIFO in this epoch */
#define MBX_H_DROP_CNT             0x02Cu   /* cpu: results not published: ring full */
#define MBX_H_ERROR_CNT            0x030u   /* cpu: producer-detected errors */
#define MBX_H_LAST_ERROR           0x034u   /* cpu: ERR_* code of the last error */
#define MBX_H_HEARTBEAT            0x038u   /* cpu: SYSCTRL CYCLE_LO, refreshed while the producer waits */
#define MBX_H_CONSUMER_INDEX       0x040u   /* ps: records consumed (free-running u32) */
#define MBX_H_CONSUMER_EPOCH       0x044u   /* ps: RESET_EPOCH the consumer is attached to */
#define MBX_H_CONSUMED_CNT         0x048u   /* ps: records consumed in this epoch */
#define MBX_H_CONSUMER_HEARTBEAT   0x04Cu   /* ps: free for the consumer (e.g. poll count) */

/* STATE */
#define MBX_STATE_INIT       0u
#define MBX_STATE_RUNNING    1u
#define MBX_STATE_DONE       2u
#define MBX_STATE_ERROR      3u

/* LAST_ERROR */
#define MBX_ERR_NONE           0u
#define MBX_ERR_BAD_CONSUMER   1u
#define MBX_ERR_CNN_CHECK      2u
#define MBX_ERR_TIMEOUT        3u
#define MBX_ERR_ARGMAX         4u

/* record word indices */
#define MBX_W_REC_HDR          0u   /* [31:16] REC_MAGIC, [15:8] REC_VERSION, [7:0] FLAGS; written last (commit) */
#define MBX_W_PUBLISH_INDEX    1u   /* ring sequence number of this record (= PRODUCER_INDEX before publishing) */
#define MBX_W_RESET_EPOCH      2u   /* producer epoch */
#define MBX_W_RESULT_INDEX     3u   /* CNN result number (CNN RES_INDEX, from 1 after a CNN reset) */
#define MBX_W_WINDOW_END_SEQ   4u   /* ESI sequence number of the last sample of the window (CNN RES_SEQ) */
#define MBX_W_ESI_TIMESTAMP    5u   /* ESI timestamp of that sample (CNN RES_TS; replay: frame number) */
#define MBX_W_CLASS            6u   /* [7:0] GESTURE (int8, post-processed), [15:8] CNN ARGMAX, [31:16] SEGMENT */
#define MBX_W_SCORE0           7u   /* int32 class score REST */
#define MBX_W_SCORE1           8u   /* int32 class score HAND_CLOSE */
#define MBX_W_SCORE2           9u   /* int32 class score HAND_OPEN */
#define MBX_W_SCORE3           10u   /* int32 class score WRIST_FLEX */
#define MBX_W_SCORE4           11u   /* int32 class score WRIST_EXT */
#define MBX_W_SCORE5           12u   /* int32 class score PINCH */
#define MBX_W_CNN_LAT_CYCLES   13u   /* CNN result latency measured by the CNN page (PL cycles) */
#define MBX_W_DETECT_CYCLE     14u   /* SYSCTRL CYCLE_LO when the RV32I saw STATUS.PENDING */
#define MBX_W_PUBLISH_CYCLE    15u   /* SYSCTRL CYCLE_LO before the commit write */

#define MBX_REC_MAGIC      0x5243u
#define MBX_REC_VERSION    1u

/* REC_HDR[7:0] flags */
#define MBX_F_POSTPROC     0x01u
#define MBX_F_DROP_BEFORE  0x02u
#define MBX_F_NEW_SEGMENT  0x04u
#define MBX_F_ARGMAX_OK    0x08u
#define MBX_F_GOLDEN_OK    0x10u
#define MBX_F_LAST         0x80u

#define MBX_GESTURE_UNCERTAIN   (-1)
#define MBX_GESTURE_NO_DECISION (-2)

#endif
